import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int M = scanner.nextInt();

        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            adj.add(new ArrayList<>());
        }

        for (int num = 2; num <= n; num++) {
            for (int target = 2 * num; target <= n; target += num) {
                adj.get(target).add(num);
            }
        }

        long[] F = new long[n + 1];
        F[1] = 1;
        if (n >= 2) {
            F[2] = 2;
        }

        for (int index = 3; index <= n; index++) {
            F[index] = (2 * F[index - 1] + F[index / (index - 1)]) % M;
            long delta_sum = 0;
            for (int neighbor : adj.get(index)) {
                if (2 <= neighbor && neighbor <= index - 2) {
                    delta_sum += F[index / neighbor] - F[(index - 1) / neighbor];
                }
            }
            F[index] = (F[index] + delta_sum) % M;
        }

        System.out.println(F[n] % M);
        scanner.close();
    }
}
